MultiLanguageSpellData['ru'][16196] = {name = "Упоение", additional_info = "[q]Когда у шамана активен \"Водный щит\", при критическом эффекте заклинаний прямого исцеления у него восстановится некоторое количество маны. При критическом эффекте заклинаний \"Волна исцеления\" и \"Великая волна исцеления\" восстановится ( 8849 * 100 / 100) ед. маны, при критическом эффекте заклинаний \"Исцеляющий всплеск\", \"Быстрина\" и \"Высвободить чары жизни\" восстановится ( 8849 * 0.6 * 100 / 100) ед. маны, а при критическом эффекте заклинания \"Цепное исцеление\" восстановится ( 8849 * 0.333 * 100 / 100) ед. маны."}
MultiLanguageSpellData['ru'][16197] = {name = "Пустой мешочек для оберега", additional_info = "Применение: 4 сек\n[q]Опустошить для изготовления мешочка для оберега."}
MultiLanguageSpellData['ru'][16213] = {name = "Очищение", additional_info = "[q]Повышает эффективность ваших исцеляющих заклинаний на 25%, количество здоровья, восполняемое вашим тотемом воды – на 50%, а заклинанием \"Целительный ливень\" – на 100%.\n\n Кроме того, исцеляющие заклинания увеличивают запас здоровья союзников на 10% от объема исцеления (но не более чем на 10% от их максимального запаса здоровья)."}
MultiLanguageSpellData['ru'][16231] = {name = "Проклятие безрассудства", additional_info = "{Мана: 70} {Радиус действия: 30 м}\nМгновенное действие\n[q]Повышает силу атаки противника на 45, но ослабляет его броню на 290 на 2 мин. Проклятые противники невосприимчивы к страху и не бегут с поля боя. Одновременно на цель может действовать только одно проклятие каждого чернокнижника."}
