MultiLanguageSpellData['ru'][51568] = {name = "[q3]Черные полярные сапоги", additional_info = "Применение: 5 сек\nИнгредиенты:\nНерубский хитин (25), Кристаллизованная вода (6)\n[q3]Черные полярные сапоги\nСтановится персональным при надевании\nСтупни Кожа\nБроня: 648\n+39 к ловкости\n+89 к выносливости\n[q2]+ 33 к критическому удару\nПрочность: 65 / 65\nТребуется"}
