MultiLanguageSpellData['ru'][53342] = {name = "Руна сокрушения чар", additional_info = "Применение: 5 сек\n[q]Гравировка на двуручном руническом оружии, уменьшающая получаемый урон от заклинаний на 4% и сокращающая время действия эффекта \"Немота\" на 50%. Для нанесения рун требуется руническая наковальня в Черном оплоте."}
