MultiLanguageSpellData['ru'][53476] = {name = "Вмешательство", additional_info = "Радиус действия: 8 - 25 м\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Питомец бросается к участнику вашей группы, снижая урон от следующей направленной против этого участника атаки на 50% от максимального запаса своего здоровья."}
MultiLanguageSpellData['ru'][53477] = {name = "Провокация", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Ваш питомец провоцирует противника на атаку. Уровень угрозы, создаваемой питомцем по отношению к этому противнику, повышается на 200%. Время действия – 3 сек."}
MultiLanguageSpellData['ru'][53478] = {name = "Ни шагу назад", additional_info = "{Мгновенное действие} {Восстановление: 6 мин}\n[q]Максимальный запас здоровья вашего питомца повышается на 30% на 20 сек. По окончании действия эффекта дополнительное здоровье теряется."}
MultiLanguageSpellData['ru'][53479] = {name = "Ни шагу назад", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Максимальный запас здоровья вашего питомца повышается на 30% на 20 сек. По окончании действия эффекта дополнительное здоровье теряется."}
MultiLanguageSpellData['ru'][53480] = {name = "Рев жертвенности", additional_info = "Радиус действия: 40 м\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Защищает союзника от критических ударов. Атаки против него не могут иметь критического эффекта, но 20% всего урона также получает питомец. Время действия – 12 сек."}
MultiLanguageSpellData['ru'][53482] = {name = "Кровь люторога", additional_info = "[q]Усиливает исцеляющие эффекты, воздействующие на вашего питомца, на 40%, повышает броню питомца на 20% и снижает вероятность того, что нанесенный ему в ближнем бою удар будет иметь критический эффект, на 6%."}
