MultiLanguageSpellData['ru'][53497] = {name = "Загнанный зверь", additional_info = "[q]Когда уровень здоровья вашего питомца опускается ниже 35%, наносимый им урон увеличивается на 50%, а вероятность того, что он получит критический урон, понижается на 60%."}
