MultiLanguageSpellData['ru'][53534] = {name = "Ледяные оковы", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Заставляет цель примерзнуть в земле на 3 сек., в течение этого времени она считается замороженной. Когда ледяные оковы разбиваются, цель восстанавливает 10% от своей обычной скорости передвижения с каждой секундой."}
MultiLanguageSpellData['ru'][53536] = {name = "Воющий ветер", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Наносит 278 в 302 ед. урона от магии льда всем противникам в радиусе 10 м. Наносит тройной урон замороженным целям."}
