MultiLanguageSpellData['ru'][53639] = {name = "Удар смерти", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Мгновенная атака на цель, наносящая 400% урона от оружия и заражающая болезнью, наносящей 8400 ед. урона в течение 21 сек. Все существующие способы исцеления действуют неправильно, значительно увеличивая потерю здоровья от болезни и не оказывая лечащего действия."}
MultiLanguageSpellData['ru'][53640] = {name = "Нечестивая порча", additional_info = "Мгновенное действие\n[q]Злобный рой нечестивых насекомых окружает заклинателя в радиусе 10 м. Наносит всем противникам в этом радиусе 0 ед. урона в секунду и поражает их болезнью, причем эффект может суммироваться до 3 раз. Время действия – 1 сек. за каждые 10 ед. силы рун. Накопление силы рун во время эффекта может его продлить."}
