MultiLanguageSpellData['ru'][54793] = {name = "Наременные осколочные гранаты", additional_info = "Применение: 5 сек\nТребуется: Пояс\nИнструменты: Тангенциальный вращатель\nИнгредиенты:\nНабор механика\n[q]Механик прикрепляет к поясу миниатюрное приспособления для сборки взрывчатых механизмов, позволяющее раз в минуту бросать термальные гранаты.\n\n Граната наносит от ( 75 * 10) до ( 100 * 10) ед. урона от огня и парализует противников в радиусе 3 м на 3 сек."}
MultiLanguageSpellData['ru'][54794] = {name = "Провокация", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 8 сек}\n[q]Заставляет противника атаковать вас. Не оказывает никакого эффекта, если противник уже атакует вас."}
MultiLanguageSpellData['ru'][54795] = {name = "Огни вуду", additional_info = "Радиус действия: 30 м\n{Мгновенное действие} {Восстановление: 15 сек}\n[q]Заклинатель окружает себя щитом пламени, который наносит 57 ед. урона от огня ближайшим противникам раз в 3 сек. Время действия – 15 сек."}
