MultiLanguageSpellData['ru'][79092] = {name = "Ненасытная стужа", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Использует всю свободную силу рун, чтобы вытянуть все тепло из земли загробника. Все противники в радиусе 10 м попадают в ледяную ловушку, которая не дает им совершать какие-либо действия в течение 6 сек."}
