MultiLanguageSpellData['ru'][79559] = {name = "Светящаяся чешуя", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Снижает вероятность уклонения противника на и противника на 20%, а ловкость – на 10% на 1 мин. Под действием этого заклинания цель не может перейти в состояние незаметности или невидимости."}
MultiLanguageSpellData['ru'][79560] = {name = "Дробящий укус", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Раскалывает доспехи противника, ослабляя броню за каждый наложенный эффект \"Раскол брони\". Суммируется до 5 раз. Время действия – 20 сек."}
MultiLanguageSpellData['ru'][79561] = {name = "Мания крови", additional_info = "Мгновенное действие\n[q]Вкус крови приводит заклинателя в исступление, увеличивая наносимый урон на 5% на 30 сек."}
MultiLanguageSpellData['ru'][79563] = {name = "Ледяной доспех", additional_info = "Мана: 630\nМгновенное действие\n[q]Увеличивает показатель брони на 2000 и сопротивление магии льда на 50. Когда противник наносит заклинателю удар, скорость его передвижения снижается на 0%, а время между атаками увеличивается на 30% на 5 сек. Маг может использовать единовременно только одно заклинание типа \"Доспех\". Время действия – 30 мин."}
MultiLanguageSpellData['ru'][79564] = {name = "Сумеречный огненный шар", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Наносит противнику урон от огня."}
