MultiLanguageSpellData['ru'][79955] = {name = "Огненный ливень", additional_info = "{Мана: 35} {Радиус действия: 30 м}\nНаправляемое (Применение: 9 сек)\n[q]Призывает раскаленный дождь пролиться, поджигая всех противников на выбранной территории и нанося им урон от огня раз в 3 сек. в течение 9 сек."}
